# Verify all 8 circuits have all 7 required stages
required_stages = {'HYDRO', 'INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE', 'PASSIVATE', 'HOLD', 'FINAL_FILL'}

with open('flush_plan.csv') as f:
    reader = csv.DictReader(f)
    circuit_stages = {}
    for row in reader:
        cid = row['circuit_id']
        stage = row['stage']
        if cid not in circuit_stages:
            circuit_stages[cid] = set()
        circuit_stages[cid].add(stage)

